{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Paliperidone, which shares the 6-fluoro-1,2-benzisoxazol-3-yl piperidine core with the query, has an absolute oral bioavailability of 28% in healthy fasting volunteers; although this is the lower end, it is still above the 20% threshold and supports high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "An immediate-release paliperidone formulation has approximately 100% absolute oral bioavailability compared with 28% for the OROS formulation; since the query is a conventional immediate-release oral drug, this supports high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Risperidone, the closest structural analogue after paliperidone, has an absolute oral bioavailability of 66% in healthy men after a 1 mg oral dose, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Melperone, a butyrophenone piperidine antipsychotic with moderate similarity, has an absolute oral bioavailability of 54 ± 24.2% from an oral syrup, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Ketanserin, a fluorophenyl piperidine with lower similarity, has an absolute oral bioavailability of 46.8% in healthy male subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Prucalopride, a propoxypiperidine with low similarity, has an absolute oral bioavailability of 93.2% in healthy fasting subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Lumateperone has an absolute oral bioavailability of only 4.4%, but its distinct polycyclic scaffold and very low structural similarity to the query limit its relevance.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Apocynin has <10% oral bioavailability, but it is a small phenolic compound with poor solubility and very low structural similarity to the query, so it provides weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues (paliperidone and risperidone) share the fluorobenzisoxazole-piperidine core and show absolute oral bioavailability of 28% (ER) to ~100% (IR) and ~66-70%, respectively; multiple other moderate-similarity CNS/piperidine drugs also show F ≥50%. Low-bioavailability analogues are structurally distant and do not outweigh the consistent high-bioavailability evidence. Therefore the query is predicted to have F ≥20% (high).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule is present in the evidence set.",
    "Paliperidone data are formulation-dependent (ER 28% vs IR ~100%), adding uncertainty to transferability.",
    "Morgan similarities to the closest analogues are only moderate (~0.45-0.47), so structural extrapolation carries some uncertainty.",
    "Low-bioavailability analogues (lumateperone, apocynin) have very low similarity and may not reflect the query's absorption and first-pass profile."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

